import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap'; // imported for compliance; not used but guarantees named import availability

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container for the node
  const container = new Group();

  // Simple plane geometry (unit size; texture will define visual size)
  const geometry = new PlaneGeometry(1, 1);

  // Basic material; will receive the texture once loaded
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });

  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // Load texture synchronously (promise resolves later)
  let loadedTexture = null;
  if (config && typeof config.imageUrl === 'string' && config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply any cinematic primitives defined in config (none expected for this node)
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive && primitive.name && ctx.primitives[primitive.name]) {
        const instance = ctx.primitives[primitive.name](container, primitive.params || {});
        primitiveInstances.push(instance);
      }
    }
  }

  // Ensure handler bucket exists
  container.userData.handlers = {};

  // Cleanup routine
  container.userData.cleanup = function cleanup() {
    // Dispose primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    }
    // Dispose GSAP timelines if any were created (none in this node)
    if (typeof gsap !== 'undefined' && gsap.globalTimeline) {
      gsap.globalTimeline.clear();
    }
    // Dispose Three.js resources
    geometry.dispose();
    material.dispose();
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
  };

  return container;
}
